        "最值得注意的，是这种变化发生在什么阶段。如果发生在重大数据、报告、会议前，往往意味着市场正在预埋仓位，价格暂时不动只是因为双方都还不愿主动打破平衡；如果发生在交割月前，则可能意味着近月仓位重组和结构再平衡；如果发生在长期横盘末端，则要警惕后续大幅波动的可能。",
