        "看紫色区间时，可以重点观察三点：第一，看当前价格在区间内还是区间外；第二，看价格是否靠近区间边缘；第三，看区间是否变宽或变窄。区间变宽，说明波动范围扩大；区间变窄，说明波动范围收缩，但这都不是方向结论。",
